import{_ as r,a,b as d}from"./chunks/amovlab_flycore_pin1_orientation.CTI7yhhL.js";import{_ as i,C as n,o as s,c as l,j as e,a as c,E as h,al as p}from"./chunks/framework.7vp1BMOE.js";const T=JSON.parse('{"title":"Amovlab Flycore","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/amovlab_flycore.md","filePath":"uk/flight_controller/amovlab_flycore.md"}'),u={name:"uk/flight_controller/amovlab_flycore.md"};function m(g,t,b,f,P,S){const o=n("Badge");return s(),l("div",null,[t[0]||(t[0]=e("h1",{id:"amovlab-flycore",tabindex:"-1"},[c("Amovlab Flycore "),e("a",{class:"header-anchor",href:"#amovlab-flycore","aria-label":'Permalink to "Amovlab Flycore"'},"​")],-1)),h(o,{type:"tip",text:"main (PX4 v2.0)"}),t[1]||(t[1]=p('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://amovlab.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The Amovlab Flycore is an STM32H743-based flight controller for PX4-powered vehicles. It integrates a UM982 GNSS module on the primary GPS interface, has dual onboard IMUs, an onboard barometer, 10 FMU PWM outputs, dual CAN, USB, three telemetry ports, an external GPS2 port, an external RC port, a standard SD card slot, and exposed buzzer and SWD pads.</p><p><img src="'+r+'" alt="Amovlab Flycore flight controller"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is intended for inclusion in the <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a> board list.</p></div><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><ul><li><strong>Processor</strong><ul><li><strong>Main FMU processor:</strong> STM32H743 (32-bit Arm® Cortex®-M7, 480 MHz, 2 MB flash, 1 MB RAM)</li><li><strong>IO processor:</strong> None. This board does not have a PX4IO coprocessor.</li></ul></li><li><strong>Sensors</strong><ul><li><strong>IMU:</strong> Bosch BMI088 (SPI), InvenSense ICM-42688P (SPI)</li><li><strong>Barometer:</strong> MS5611 (SPI)</li><li><strong>GNSS:</strong> Onboard UM982 module connected to <code>GPS1</code></li><li><strong>Magnetometer:</strong> None fitted by default. <code>GPS1</code> and <code>GPS2</code> do not include compass I2C lines.</li></ul></li><li><strong>Interfaces</strong><ul><li><strong>PWM outputs:</strong> 10 FMU outputs</li><li><strong>Serial ports:</strong> 7</li><li><strong>Telemetry ports:</strong> 3 (<code>TELEM1</code>, <code>TELEM2</code>, <code>TELEM3</code>)</li><li><strong>GPS ports:</strong> 2 <ul><li><code>GPS1</code>: internal connection to the onboard UM982 GNSS module</li><li><code>GPS2</code>: external GPS connector</li></ul></li><li><strong>I2C ports:</strong> 2 external buses configured in firmware (<code>I2C1</code>, <code>I2C4</code>)</li><li><strong>SPI buses:</strong> 3 <ul><li><code>SPI1</code>: BMI088 IMU and MS5611 barometer</li><li><code>SPI2</code>: ICM-42688P IMU</li><li><code>SPI4</code>: onboard flash</li></ul></li><li><strong>CAN buses:</strong> 2</li><li><strong>USB:</strong> Yes</li><li><strong>RC input:</strong> Yes, on the FMU <code>RC</code> port</li><li><strong>Supported RC protocols:</strong> SBUS, DSM/DSMX, CRSF, GHST, PPM</li><li><strong>Analog battery inputs:</strong> 1 voltage input and 1 current input</li><li><strong>Additional analog inputs:</strong> None exposed to users</li><li><strong>Buzzer:</strong> Exposed pads</li><li><strong>SWD:</strong> Exposed pads</li><li><strong>SD card:</strong> Standard SD card slot</li></ul></li><li><strong>Electrical data</strong><ul><li><strong>Power input:</strong> XT30 connector, 15-28 V</li><li><strong>Minimum input current:</strong> 0.1 A</li><li><strong>Battery voltage sensing range:</strong> 3S-6S LiPo</li><li><strong>Battery current sensing range:</strong> 1-60 A</li><li><strong>Servo/PWM output rail:</strong> Externally powered. The board only provides PWM signal outputs.</li></ul></li><li><strong>Mechanical data</strong><ul><li><strong>Dimensions:</strong> 120 mm x 55 mm x 26.3 mm</li><li><strong>Weight:</strong> 60 g</li><li><strong>Mounting:</strong> 50 mm x 115 mm hole spacing, 2.5 mm hole diameter</li></ul></li></ul><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><p>For purchasing, contact <a href="mailto:shudajun@amovauto.com" target="_blank" rel="noreferrer">shudajun@amovauto.com</a>.</p><h2 id="з-єднання" tabindex="-1">З&#39;єднання <a class="header-anchor" href="#з-єднання" aria-label="Permalink to &quot;З&#39;єднання&quot;">​</a></h2><p>The board includes the following main external connections:</p><ul><li><code>POWER</code>: XT30, 15-28 V input</li><li><code>USB</code></li><li><code>TELEM1</code></li><li><code>TELEM2</code></li><li><code>TELEM3</code></li><li><code>GPS2</code>: external GPS connector, without compass I2C</li><li><code>RC</code></li><li><code>CAN1</code></li><li><code>CAN2</code></li><li><code>I2C1</code></li><li><code>I2C4</code></li><li><code>PWM OUT 1-10</code></li><li>Standard SD card slot</li><li>Buzzer pads</li><li>SWD pads</li><li>UART8 debug console pads</li></ul><p>The external peripheral signal connectors use JST GH connectors with 1.25 mm pitch. Flycore uses Pixhawk-style port names for common interfaces such as <code>TELEM</code>, <code>GPS</code>, <code>CAN</code>, <code>I2C</code>, and <code>RC</code>, but the fitted connectors and pin assignments are board-specific and are not claimed to fully comply with the DS-009 Pixhawk Connector Standard. Use the <a href="#pinouts">Pinouts</a> section as the authoritative connector definition for this board. This does not apply to <code>POWER</code> (XT30), USB, the SD card slot, RTK antenna interfaces, or the exposed buzzer, SWD, and UART8 debug console pads.</p><p><code>GPS1</code> is not exposed as an external connector on the flight controller. It is connected internally to the onboard UM982 GNSS module and does not include safety-switch pins or compass I2C lines.</p><h2 id="schematic-diagram" tabindex="-1">Schematic Diagram <a class="header-anchor" href="#schematic-diagram" aria-label="Permalink to &quot;Schematic Diagram&quot;">​</a></h2><p><img src="'+a+'" alt="Amovlab Flycore connector layout"></p><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><p>The following pinouts use the signal names from the manufacturer interface definition. Pin 1 starts from the right side of the connector, as shown below:</p><p><img src="'+d+'" alt="Amovlab Flycore pin 1 orientation"></p><h3 id="can1-port" tabindex="-1">CAN1 Port <a class="header-anchor" href="#can1-port" aria-label="Permalink to &quot;CAN1 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>CAN_L</td></tr><tr><td>2</td><td>CAN_H</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>VCC</td></tr></tbody></table><h3 id="gps2-port" tabindex="-1">GPS2 Port <a class="header-anchor" href="#gps2-port" aria-label="Permalink to &quot;GPS2 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>RX</td></tr><tr><td>2</td><td>TX</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>VCC</td></tr></tbody></table><h3 id="telem3-port" tabindex="-1">TELEM3 Port <a class="header-anchor" href="#telem3-port" aria-label="Permalink to &quot;TELEM3 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>RX</td></tr><tr><td>2</td><td>TX</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>VCC</td></tr></tbody></table><h3 id="i2c1-port" tabindex="-1">I2C1 Port <a class="header-anchor" href="#i2c1-port" aria-label="Permalink to &quot;I2C1 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>SDA</td></tr><tr><td>2</td><td>SCL</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>VCC</td></tr></tbody></table><h3 id="i2c4-port" tabindex="-1">I2C4 Port <a class="header-anchor" href="#i2c4-port" aria-label="Permalink to &quot;I2C4 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>SDA</td></tr><tr><td>2</td><td>SCL</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>VCC</td></tr></tbody></table><h3 id="pwm-port" tabindex="-1">PWM Port <a class="header-anchor" href="#pwm-port" aria-label="Permalink to &quot;PWM Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>GND</td></tr><tr><td>2</td><td>BUZZER</td></tr><tr><td>3</td><td>FMU_CH8</td></tr><tr><td>4</td><td>FMU_CH7</td></tr><tr><td>5</td><td>FMU_CH6</td></tr><tr><td>6</td><td>FMU_CH5</td></tr><tr><td>7</td><td>FMU_CH4</td></tr><tr><td>8</td><td>FMU_CH3</td></tr><tr><td>9</td><td>FMU_CH2</td></tr><tr><td>10</td><td>FMU_CH1</td></tr></tbody></table><h3 id="telem2-port" tabindex="-1">TELEM2 Port <a class="header-anchor" href="#telem2-port" aria-label="Permalink to &quot;TELEM2 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>GND</td></tr><tr><td>2</td><td>RX</td></tr><tr><td>3</td><td>TX</td></tr></tbody></table><h3 id="rtk-com2-port" tabindex="-1">RTK COM2 Port <a class="header-anchor" href="#rtk-com2-port" aria-label="Permalink to &quot;RTK COM2 Port&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>RX</td></tr><tr><td>2</td><td>TX</td></tr><tr><td>3</td><td>GND</td></tr><tr><td>4</td><td>PPS</td></tr></tbody></table><h2 id="sensor-and-bus-configuration" tabindex="-1">Sensor and Bus Configuration <a class="header-anchor" href="#sensor-and-bus-configuration" aria-label="Permalink to &quot;Sensor and Bus Configuration&quot;">​</a></h2><p>The default Flycore PX4 port matches the hardware as shipped:</p><ul><li><strong>Onboard sensors:</strong> BMI088, ICM-42688P, and MS5611.</li><li><strong>Onboard GNSS:</strong> UM982 connected to <code>GPS1</code>.</li><li><strong>External GPS:</strong> <code>GPS2</code> is available for an external GPS receiver, but does not provide compass I2C lines.</li><li><strong>Default firmware:</strong> <code>rc.board_sensors</code> starts only the onboard IMUs and barometer. It does not start magnetometers or other external sensors that are not fitted by default.</li></ul><p>Flycore has no onboard magnetometer and its GPS connectors do not include compass I2C. If a magnetometer is required, use a supported external magnetometer connected through <code>I2C1</code>, <code>I2C4</code>, or another compatible interface provided by the vehicle setup.</p><p>Without a magnetometer, yaw in flight relies on GPS course when available and other estimator settings as configured in QGroundControl. Plan missions accordingly for GPS-denied operation.</p><h2 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power {#power}&quot;">​</a></h2><p>The flight controller can be powered from the <strong>POWER</strong> connector.</p><p>Power ports:</p><ul><li><code>POWER</code>: XT30 connector, 15-28 V input, 0.1 A minimum input current</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The PWM output ports are not powered by the POWER port. The output rail must be <a href="./../peripherals/pwm_escs_and_servo">separately powered</a> if it needs to power servos or other hardware. This is generally true for VTOL and fixed-wing vehicles, but not necessarily true for multicopters.</p></div><p>The battery voltage sensing range is 3S-6S LiPo.</p><p>The battery current sensing range is 1-60 A.</p><p>PX4 configures analog battery monitoring using <code>BAT1_V_DIV=10.89</code> and <code>BAT1_A_PER_V=36.367515152</code> by default. The board only provides PWM signal outputs; provide external rail power before connecting servos or other payloads that need power from the output rail.</p><p>For battery and power module configuration see <a href="./../config/battery">Battery and Power Module Setup</a>.</p><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th><th style="text-align:center;">Flow Control</th></tr></thead><tbody><tr><td>USART2</td><td>/dev/ttyS0</td><td><code>TELEM1</code></td><td style="text-align:center;">Так</td></tr><tr><td>USART3</td><td>/dev/ttyS1</td><td><code>TELEM2</code></td><td style="text-align:center;">Ні</td></tr><tr><td>UART4</td><td>/dev/ttyS2</td><td><code>GPS1</code></td><td style="text-align:center;">Ні</td></tr><tr><td>UART5</td><td>/dev/ttyS3</td><td><code>TELEM3</code></td><td style="text-align:center;">Ні</td></tr><tr><td>USART6</td><td>/dev/ttyS4</td><td><code>RC</code></td><td style="text-align:center;">Ні</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td><code>GPS2</code></td><td style="text-align:center;">Ні</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td><code>Debug Console</code></td><td style="text-align:center;">Ні</td></tr></tbody></table><p><code>GPS1</code> is used by the onboard UM982 GNSS module. <code>GPS2</code> is the external GPS port. The debug console is exposed on UART8 pads; no connector is fitted by default. The UART8 pad pinout is board-specific.</p><h2 id="radio_control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio_control" aria-label="Permalink to &quot;Radio Control {#radio_control}&quot;">​</a></h2><p>Для того щоб керувати транспортним засобом <em>вручну</em>, потрібна система радіоуправління (RC) (PX4 не потребує системи радіоуправління для автономних режимів польоту).</p><p>Вам потрібно <a href="./../getting_started/rc_transmitter_receiver">вибрати сумісний передавач/приймач</a> і <em>зв&#39;язати</em> їх таким чином, щоб вони взаємодіяли (ознайомтеся з інструкціями, що додаються до вашого конкретного передавача/приймача).</p><p>The RC port is connected to the FMU, not to a PX4IO coprocessor.</p><p>The <code>RC</code> port supports SBUS, DSM/DSMX, CRSF, GHST, and PPM receivers. The board configuration enables PX4 RC input and maps the RC serial port to <code>/dev/ttyS4</code>.</p><p>For PPM and S.Bus receivers, a single signal wire carries all channels. If your receiver outputs individual PWM signals (one wire per channel) it must be connected via a PPM encoder. For more information, see <a href="./../getting_started/rc_transmitter_receiver">RC receivers</a>.</p><h2 id="gps_compass" tabindex="-1">GPS &amp; Compass <a class="header-anchor" href="#gps_compass" aria-label="Permalink to &quot;GPS &amp; Compass {#gps_compass}&quot;">​</a></h2><p>PX4 supports GPS modules connected to the GPS port(s) listed below. GPS modules should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible, with the direction marker pointing towards the front of the vehicle.</p><p>The GPS ports are:</p><ul><li><code>GPS1</code> (FMU): Internal connection to the onboard UM982 GNSS module. This is not exposed as an external connector and does not include safety-switch pins or compass I2C lines.</li><li><code>GPS2</code> (FMU): External GPS connector. This port does not include compass I2C lines.</li></ul><p>Flycore has no onboard magnetometer. The <code>GPS1</code> and <code>GPS2</code> interfaces do not provide compass I2C, so a GPS/compass module connected to <code>GPS2</code> will only use the GPS serial interface unless the compass is connected through another compatible external interface.</p><h2 id="telemetry" tabindex="-1">Telemetry Radios (Optional) <a class="header-anchor" href="#telemetry" aria-label="Permalink to &quot;Telemetry Radios (Optional) {#telemetry}&quot;">​</a></h2><p><a href="./../telemetry/">Телеметричні радіостанції</a> можуть використовуватися для зв&#39;язку та управління транспортним засобом у польоті з наземної станції (наприклад, ви можете направляти БПЛА до певної позиції або завантажувати нове завдання).</p><p>The vehicle-based radio should be connected to a TELEM port — <strong>TELEM1</strong>, <strong>TELEM2</strong>, or <strong>TELEM3</strong>. If connected to <strong>TELEM1</strong>, no further configuration is required. Інша радіостанція підключається до вашого комп&#39;ютера або мобільного пристрою наземної станції (зазвичай за допомогою USB).</p><h2 id="pwm_outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm_outputs" aria-label="Permalink to &quot;PWM Outputs {#pwm_outputs}&quot;">​</a></h2><p>This flight controller supports up to 10 FMU PWM outputs (<code>MAIN</code>).</p><p>Outputs 1-7 support <a href="./../peripherals/dshot">DShot</a> and <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a>.</p><p>Outputs 8-10 do not support DShot.</p><p>The 10 outputs are split into 3 groups:</p><ul><li>Outputs 1-4 are in group 1, using Timer 1.</li><li>Outputs 5-7 are in group 2, using Timer 3.</li><li>Outputs 8-10 are in group 3, using Timer 4.</li></ul><p>All outputs within the same group must use the same output protocol and rate.</p><h2 id="sd-карта" tabindex="-1">SD-карта <a class="header-anchor" href="#sd-карта" aria-label="Permalink to &quot;SD-карта&quot;">​</a></h2><p>This board has a standard SD card slot.</p><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> amovlab_flycore_default</span></span></code></pre></div><p>Build and upload via USB:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> amovlab_flycore_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div><p>Build the bootloader:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> amovlab_flycore_bootloader</span></span></code></pre></div><h2 id="bootloader-board-id" tabindex="-1">Bootloader / Board ID <a class="header-anchor" href="#bootloader-board-id" aria-label="Permalink to &quot;Bootloader / Board ID&quot;">​</a></h2><ul><li><strong>Board ID:</strong> 1218 (<code>boards/amovlab/flycore/firmware.prototype</code>)</li><li><strong>Bootloader USB product string:</strong> <code>PX4 BL AMOV FLYCORE</code></li></ul><h2 id="default-airframe" tabindex="-1">Default Airframe <a class="header-anchor" href="#default-airframe" aria-label="Permalink to &quot;Default Airframe&quot;">​</a></h2><p>For hardware type <code>FLYCORE000000</code>, <code>rc.board_defaults</code> sets <code>SYS_AUTOSTART</code> to <strong>4014</strong> (generic multicopter airframe class).</p><p>Adjust the airframe in QGroundControl to match your vehicle.</p><p>Amovlab recommends this flight controller for the Amovlab SU17 platform.</p><h2 id="відладочнии-порт" tabindex="-1">Відладочний порт <a class="header-anchor" href="#відладочнии-порт" aria-label="Permalink to &quot;Відладочний порт&quot;">​</a></h2><p>The PX4 system console is exposed on UART8 pads. No connector is fitted by default.</p><p>The UART8 pad pinout is board-specific and does not use a standard fitted connector.</p><h2 id="підтримувані-платформи-конструкціі" tabindex="-1">Підтримувані платформи / Конструкції <a class="header-anchor" href="#підтримувані-платформи-конструкціі" aria-label="Permalink to &quot;Підтримувані платформи / Конструкції&quot;">​</a></h2><p>The Flycore can be used with airframes supported by the selected PX4 configuration, including multicopters and other vehicles that match the available PWM, CAN, serial, and sensor interfaces.</p><p>Amovlab recommends Flycore for the Amovlab SU17 platform.</p><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><ul><li><strong>Vendor:</strong> Amovlab</li><li><strong>PX4 board target:</strong> <code>amovlab_flycore_default</code></li><li><strong>PX4 hardware architecture:</strong> <code>AMOVLAB_FLYCORE</code></li><li><strong>PX4 hardware type:</strong> <code>FLYCORE000000</code></li><li><strong>Hardware version/revision:</strong> <code>0x000</code> / <code>0x000</code></li></ul>',95))])}const v=i(u,[["render",m]]);export{T as __pageData,v as default};
